}
:where(
  .roc-shadcn h1,
  .roc-shadcn h2,
  .roc-shadcn h3,
  .roc-shadcn p,
  .roc-shadcn pre,
  h1.roc-shadcn,
  h2.roc-shadcn,
  h3.roc-shadcn,
  p.roc-shadcn,
